DROP TABLE IF EXISTS `wo_sop_execution`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wo_sop_execution` (
  `id` int NOT NULL AUTO_INCREMENT,
  `work_order_id` int NOT NULL,
  `bom_step_id` int NOT NULL,
  `sequence` int NOT NULL,
  `is_completed` tinyint(1) NOT NULL DEFAULT '0',
  `actual_parameters` text,
  `operator_id` int DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `verifier_id` int DEFAULT NULL,
  `verified_at` datetime DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'pending',
  `notes` text,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `line_clearance_confirmed` tinyint(1) NOT NULL DEFAULT '0',
  `line_clearance_by` int DEFAULT NULL,
  `line_clearance_at` datetime DEFAULT NULL,
  `pm_approved_by` int DEFAULT NULL,
  `pm_approved_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
